using HarmonyLib;
using UnityEngine;
using static LightInDark.Utilities.AmongUsEdited;

namespace Light.Patches
{
    [HarmonyPatch(typeof(DisconnectPopup), nameof(DisconnectPopup.SetText))]
    public static class DisconnectPopupPatch
    {
        [HarmonyPrefix]
        public static bool Prefix(DisconnectPopup __instance)
        {
            if (string.IsNullOrEmpty(KickManager.kickReason))
                return true;
            float now = Time.realtimeSinceStartup;
            if (KickManager.kickReasonConsumeUntil > 0f)
            {
                if (now > KickManager.kickReasonConsumeUntil)
                {
                    KickManager.Clear();
                    return true;
                }
            }
            else if (now > KickManager.kickReasonWaitUntil)
            {
                KickManager.Clear();
                return true;
            }
            else
            {
                KickManager.kickReasonConsumeUntil = now + 3f;
            }
            __instance._textArea.text = KickManager.kickReason;
            __instance.OnTextChanged();
            return false;
        }
    }
}

using Light.UI.Help;

namespace Light.Patches;

/// <summary>H 键帮助菜单开关</summary>
[HarmonyPatch(typeof(HudManager), nameof(HudManager.Update))]
public static class HelpKeyPatch
{
    public static void Postfix()
    {
        // ESC 关闭
        if (Input.GetKeyDown(KeyCode.Escape) && HelpScreen.OpenedAnyHelpScreen)
            HelpScreen.TryCloseHelpScreen();
        // H 打开
        if (Input.GetKeyDown(KeyCode.H) && CanOpenHelp())
            HelpScreen.TryOpenHelpScreen();
    }

    /// <summary>是否可以打开帮助（防重复 / 聊天输入 / 占用状态）</summary>
    private static bool CanOpenHelp()
    {
        if (HelpScreen.OpenedAnyHelpScreen) return false;
        // 聊天输入框聚焦时屏蔽
        var chat = HudManager.Instance?.Chat;
        if (chat != null && chat.freeChatField != null && chat.freeChatField.textArea != null && chat.freeChatField.textArea.hasFocus)
            return false;
        if (Minigame.Instance != null) return false;
        if (IntroCutscene.Instance != null) return false;
        if (ExileController.Instance != null) return false;
        return true;
    }
}

